const {chromium}=require('playwright');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1300,height:800}});const e=[];p.on('pageerror',x=>e.push(x.message));await p.goto('file:///home/claude/autohound/index.html');await p.waitForTimeout(700);await p.evaluate(()=>[...document.images].forEach(i=>i.loading='eager'));await p.waitForTimeout(500);console.log(await p.title(),await p.locator('.window').count(),await p.evaluate(()=>[...document.images].filter(i=>i.complete&&!i.naturalWidth).length),e);await b.close()})()
